script:
// TASK: place an isometric 3D view on a sheet, fit it to the REAL sheet size, and add text-note
// callout leaders without corrupting them. Runs in a fresh scratch PROJECT document so it touches
// no open model -- against your real project use the `Document` global and your own view/sheet. The
// scratch project stays OPEN after the run; close it by title later (documents-create-write-and-close).
var proj = Connector.CreateProjectDocument();
System.Console.WriteLine("cleanup-title=" + proj.Title + ";");
Autodesk.Revit.DB.Level level = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(proj).OfClass(typeof(Autodesk.Revit.DB.Level))) { if (level == null || l.Elevation < level.Elevation) level = l; }
Autodesk.Revit.DB.ElementId v3dTypeId = null;
foreach (Autodesk.Revit.DB.ViewFamilyType t in new Autodesk.Revit.DB.FilteredElementCollector(proj).OfClass(typeof(Autodesk.Revit.DB.ViewFamilyType))) { if (t.ViewFamily == Autodesk.Revit.DB.ViewFamily.ThreeDimensional) { v3dTypeId = t.Id; break; } }
Autodesk.Revit.DB.FamilySymbol tbSym = null;
foreach (Autodesk.Revit.DB.FamilySymbol s in new Autodesk.Revit.DB.FilteredElementCollector(proj).OfClass(typeof(Autodesk.Revit.DB.FamilySymbol)).OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_TitleBlocks)) { tbSym = s; break; }
Autodesk.Revit.DB.ElementId textTypeId = null;
foreach (Autodesk.Revit.DB.TextNoteType t in new Autodesk.Revit.DB.FilteredElementCollector(proj).OfClass(typeof(Autodesk.Revit.DB.TextNoteType))) { textTypeId = t.Id; break; }

// 1. Setup + isometric view + sheet + viewport.
var ids = Connector.WithTransaction(proj, () => {
  for (int i = 0; i < 4; i++) Autodesk.Revit.DB.Wall.Create(proj, Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(i*6, 0, 0), new Autodesk.Revit.DB.XYZ(i*6, 20, 0)), level.Id, false);
  var v = Autodesk.Revit.DB.View3D.CreateIsometric(proj, v3dTypeId);
  if (tbSym != null && !tbSym.IsActive) tbSym.Activate();
  var sheet = Autodesk.Revit.DB.ViewSheet.Create(proj, tbSym != null ? tbSym.Id : Autodesk.Revit.DB.ElementId.InvalidElementId);
  sheet.SheetNumber = "A-3D" + (System.DateTime.UtcNow.Ticks % 100000); sheet.Name = "Overview";
  proj.Regenerate();
  var vp = Autodesk.Revit.DB.Viewport.Create(proj, sheet.Id, v.Id, new Autodesk.Revit.DB.XYZ(0.7, 0.5, 0));
  proj.Regenerate();
  return new System.Collections.Generic.List<Autodesk.Revit.DB.ElementId> { v.Id, sheet.Id, vp.Id };
});
var view3d = proj.GetElement(ids[0]) as Autodesk.Revit.DB.View3D;
var sheetEl = proj.GetElement(ids[1]) as Autodesk.Revit.DB.ViewSheet;
var vpEl = proj.GetElement(ids[2]) as Autodesk.Revit.DB.Viewport;

// 2. CONFIRM the real sheet size before positioning (an 11x17 sheet is ~1.42 x 0.92 ft; coordinates
//    that suit a D-size sheet fall off a small one).
Autodesk.Revit.DB.Element tbInst = null;
foreach (var e in new Autodesk.Revit.DB.FilteredElementCollector(proj, sheetEl.Id).OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_TitleBlocks)) { tbInst = e; break; }
double sheetW = tbInst.LookupParameter("Sheet Width").AsDouble();
double sheetH = tbInst.LookupParameter("Sheet Height").AsDouble();
int scaleBefore = view3d.Scale;
var oB = vpEl.GetBoxOutline();
double bW = oB.MaximumPoint.X-oB.MinimumPoint.X, bH = oB.MaximumPoint.Y-oB.MinimumPoint.Y;

// 3. Fit: on-sheet box size is inversely proportional to View.Scale (double the Scale => half the
//    display size). First estimate, then measure-and-adjust: Viewport.GetBoxOutline INCLUDES the
//    viewport label, so a single estimate can run slightly large.
int applied = (int)System.Math.Ceiling(scaleBefore * System.Math.Max(bW/(sheetW*0.85), bH/(sheetH*0.85)));
int a0 = applied;
Connector.WithTransaction(proj, () => { view3d.Scale = a0; return true; });
Connector.WithTransaction(proj, () => { vpEl.SetBoxCenter(new Autodesk.Revit.DB.XYZ(sheetW/2.0, sheetH/2.0, 0)); return true; });
int iters = 0;
for (; iters < 6; iters++) {
  var ob = vpEl.GetBoxOutline();
  if ((ob.MaximumPoint.X-ob.MinimumPoint.X) <= sheetW*0.98 && (ob.MaximumPoint.Y-ob.MinimumPoint.Y) <= sheetH*0.98) break;
  applied = (int)System.Math.Ceiling(applied * 1.1);
  int a2 = applied;
  Connector.WithTransaction(proj, () => { view3d.Scale = a2; return true; });
  Connector.WithTransaction(proj, () => { vpEl.SetBoxCenter(new Autodesk.Revit.DB.XYZ(sheetW/2.0, sheetH/2.0, 0)); return true; });
}
int scaleAfter = view3d.Scale;
var oA = vpEl.GetBoxOutline();
bool boxFitsSheet = oA.MinimumPoint.X >= -0.01 && oA.MaximumPoint.X <= sheetW + 0.01 && oA.MinimumPoint.Y >= -0.01 && oA.MaximumPoint.Y <= sheetH + 0.01;

// 4. Callout leaders on the SHEET. TextNote leaders are AddLeader/GetLeaders with settable
//    Leader.End/.Elbow (a different API from RoomTag/IndependentTag). For each: MOVE the note to its
//    label spot FIRST, THEN set the absolute Leader geometry -- ElementTransformUtils.MoveElement
//    rigidly translates existing leader points too, so setting them before the move shifts them twice.
var leaderCheck = Connector.WithTransaction(proj, () => {
  var results = new System.Collections.Generic.List<object>();
  var o = vpEl.GetBoxOutline();
  var labelSpots = new Autodesk.Revit.DB.XYZ[] { new Autodesk.Revit.DB.XYZ(0.15, sheetH-0.1, 0), new Autodesk.Revit.DB.XYZ(sheetW-0.3, 0.12, 0) };
  var targets = new Autodesk.Revit.DB.XYZ[] { new Autodesk.Revit.DB.XYZ(o.MinimumPoint.X+0.1, o.MinimumPoint.Y+0.1, 0), new Autodesk.Revit.DB.XYZ(o.MaximumPoint.X-0.1, o.MaximumPoint.Y-0.1, 0) };
  for (int i = 0; i < labelSpots.Length; i++) {
    var note = Autodesk.Revit.DB.TextNote.Create(proj, sheetEl.Id, new Autodesk.Revit.DB.XYZ(0.5, 0.5, 0), "Room " + (i+1), textTypeId);
    proj.Regenerate();
    note.AddLeader(Autodesk.Revit.DB.TextNoteLeaderTypes.TNLT_STRAIGHT_R);
    proj.Regenerate();
    Autodesk.Revit.DB.ElementTransformUtils.MoveElement(proj, note.Id, labelSpots[i] - note.Coord);   // move FIRST
    proj.Regenerate();
    var ld = note.GetLeaders()[0];
    ld.End = targets[i];                                                                                // THEN set leader geometry
    ld.Elbow = new Autodesk.Revit.DB.XYZ((labelSpots[i].X + targets[i].X)/2.0, labelSpots[i].Y, 0);
    proj.Regenerate();
    var chk = note.GetLeaders()[0];
    results.Add(new { endMatches = System.Math.Abs(chk.End.X - targets[i].X) < 1e-6 && System.Math.Abs(chk.End.Y - targets[i].Y) < 1e-6 });
  }
  return results;
});

return new { sheetWidthFt = sheetW, sheetHeightFt = sheetH, scaleBefore, scaleAfter, fitIterations = iters, boxFitsSheet, leaderCheck };
